// BREVO — API Email (pas de SMTP, port 443)
// ─────────────────────────────────────────
let emailConfig = null;

function initEmail() {
  if (!process.env.BREVO_API_KEY || !process.env.EMAIL_FROM) {
    console.log("⚠️ Email non configuré (BREVO_API_KEY / EMAIL_FROM manquants)");
    return;
  }
  emailConfig = {
    apiKey: process.env.BREVO_API_KEY,
    from: process.env.EMAIL_FROM,
    fromName: "Royal Tchitchi 👑",
  };
  console.log(`📧 Email Brevo configuré : ${emailConfig.from}`);
}

// Fonction d'envoi via API Brevo (port 443 - pas bloqué par Render)
async function envoyerEmail(to, subject, html) {
  if (!emailConfig) return false;
  try {
    const resp = await axios.post(
      "https://api.brevo.com/v3/smtp/email",
      {
        sender: { name: emailConfig.fromName, email: emailConfig.from },
        to: [{ email: to }],
        replyTo: { name: emailConfig.fromName, email: emailConfig.from },
        subject,
        htmlContent: html,
      },
      {
        headers: {
          "api-key": emailConfig.apiKey,
          "Content-Type": "application/json",
        },
      }
    );
    return resp.status === 201;
  } catch (err) {
    console.error("Erreur Brevo :", err.response?.data || err.message);
    return false;
  }
}

