let calendar = null;
let driveClient = null;
const DRIVE_FOLDER_ID = process.env.DRIVE_FOLDER_ID || "1fAYhULRDW7fPxUXkMWgMH1QMJhXvzSq5";

function initGoogleCalendar() {
  try {
    const credentials = JSON.parse(process.env.GOOGLE_SERVICE_ACCOUNT);
    const auth = new google.auth.GoogleAuth({
      credentials,
      scopes: [
        "https://www.googleapis.com/auth/calendar",
        "https://www.googleapis.com/auth/drive",
      ]
    });
    const authClient = auth;
    calendar = google.calendar({ version: "v3", auth: authClient });
    driveClient = google.drive({ version: "v3", auth: authClient });
    console.log("📅 Google Calendar + Drive connectés !");
  } catch (err) {
    console.error("❌ Google Calendar/Drive :", err.message);
  }
}

// Upload une image Buffer sur Drive et retourne l'URL publique
async function uploadImageDrive(imageBuffer, fileName, mimeType = "image/jpeg") {
  if (!driveClient) return null;
  try {
    const { Readable } = require("stream");
    const stream = Readable.from(imageBuffer);
    const res = await driveClient.files.create({
      requestBody: {
        name: fileName,
        parents: [DRIVE_FOLDER_ID],
      },
      media: { mimeType, body: stream },
      fields: "id",
    });
    const fileId = res.data.id;
    // Rendre le fichier public
    await driveClient.permissions.create({
      fileId,
      requestBody: { role: "reader", type: "anyone" },
    });
    const url = `https://drive.google.com/uc?export=view&id=${fileId}`;
    console.log(`📸 Photo uploadée sur Drive: ${url}`);
    return url;
  } catch (err) {
    console.error("❌ Drive upload:", err.message);
    return null;
  }
}

// URL du logo Royal Tchitchi sur Drive
let LOGO_DRIVE_URL = null;
const LOGO_B64_CONST = "";

// Uploader le logo Royal Tchitchi sur Drive au démarrage
async function uploaderLogoRoyal() {
  if (!driveClient) return;
  try {
    // Vérifier si le logo existe déjà sur Drive
    const res = await driveClient.files.list({
      q: `name='royal_tchitchi_logo.jpg' and '${DRIVE_FOLDER_ID}' in parents and trashed=false`,
      fields: "files(id,name)",
    });
    if (res.data.files && res.data.files.length > 0) {
      LOGO_DRIVE_URL = `https://drive.google.com/uc?export=view&id=${res.data.files[0].id}`;
      console.log(`✅ Logo Royal Tchitchi Drive: ${LOGO_DRIVE_URL}`);
      return;
    }
    // Sinon uploader le logo depuis le code
    const logoBase64 = "";
    const buffer = Buffer.from(logoBase64, 'base64');
    LOGO_DRIVE_URL = await uploadImageDrive(buffer, 'royal_tchitchi_logo.jpg');
    console.log(`✅ Logo Royal Tchitchi uploadé: ${LOGO_DRIVE_URL}`);
  } catch (err) {
    console.error("❌ Upload logo:", err.message);
  }
}

