async function sendMessage(chatId, text, options = {}) {
  try {
    await axios.post(`${TELEGRAM_API}/sendMessage`, { chat_id: chatId, text, parse_mode: "Markdown", ...options });
  } catch (err) { console.error("Erreur sendMessage :", err.message); }
}

